export default {
  id: "bouncing-ball",
  title: "Bouncing Ball",
  knobs: {
    size: { value: 36, min: 16, max: 80, label: "Ball size" },
    bounciness: { value: 0.82, min: 0.3, max: 0.98, label: "Bounciness" },
    speed: { value: 160, min: 0, max: 400, label: "Horizontal speed" },
    gravity: { value: 1500, min: 500, max: 3000, label: "Gravity" }
  },
  setup(api: any, knobs: Record<string, number | string | boolean>) {
    const size = Number(knobs.size) || 36;
    const bounce = Number(knobs.bounciness) || 0.82;
    const speed = Number(knobs.speed) || 160;
    const gravity = Number(knobs.gravity) || 1500;
    const groundY = 400;
    api.spawn({ type: "ground", x: -200, y: groundY, w: 1200, h: 48, solid: true, gravityScale: 0, color: 0x4a7c3a });
    const ball = api.spawn({ type: "bouncing-ball", x: 120, y: groundY - size - 160, w: size, h: size, vx: 0, vy: 0, solid: false, gravityScale: 0, color: 0xff5533, data: { vy: 0, vx: speed, bounces: 0, groundY } });
    api.onTick((dt: number) => {
      const b = api.byType("bouncing-ball")[0];
      if (!b) return;
      b.data.vy = (Number(b.data.vy) || 0) + gravity * dt;
      b.data.vx = Number(b.data.vx) || speed;
      b.x += b.data.vx * dt;
      b.y += b.data.vy * dt;
      if (b.x < 0) { b.x = 0; b.data.vx = Math.abs(b.data.vx); }
      if (b.x + b.w > 800) { b.x = 800 - b.w; b.data.vx = -Math.abs(b.data.vx); }
      const floor = Number(b.data.groundY) || groundY;
      if (b.y + b.h >= floor && b.data.vy > 0) {
        b.y = floor - b.h;
        b.data.vy = -b.data.vy * bounce;
        if (Math.abs(b.data.vy) < 120) b.data.vy = -320 - api.rand() * 120;
        b.data.bounces = (Number(b.data.bounces) || 0) + 1;
        api.burst(b.x + b.w / 2, floor, 0xff5533, 6);
      }
      if (b.y < 0 && b.data.vy < 0) { b.y = 0; b.data.vy = -b.data.vy; }
      b.vx = b.data.vx;
      b.vy = b.data.vy;
      void ball;
    });
  },
  dispose(api: any) {
    for (const e of [...api.byType("bouncing-ball")]) api.despawn(e.id);
    for (const e of [...api.byType("ground")]) api.despawn(e.id);
  },
  test(t: any) {
    const balls = t.api.byType("bouncing-ball");
    t.expect(balls.length === 1, "one bouncing ball spawned");
    const startY = balls[0].y;
    t.step(30);
    t.expect(balls[0].y !== startY, "ball falls under gravity");
    t.step(120);
    t.expect((Number(balls[0].data.bounces) || 0) >= 1, "ball bounced on the ground");
    t.expect(balls[0].y + balls[0].h <= 401, "ball stays above ground");
  }
};

