export default {
  id: "patrolling-robot",
  title: "Patrolling Robot",
  knobs: {
    speed: { value: 90, min: 20, max: 240, label: "Patrol speed" },
    range: { value: 130, min: 40, max: 320, label: "Patrol range" },
    size: { value: 46, min: 28, max: 80, label: "Robot size" }
  },
  setup(api: any, knobs: any) {
    const size = Number(knobs.size) || 46;
    const robot = api.spawn({
      type: "robot",
      x: 160,
      y: 400 - size,
      w: Math.round(size * 0.82),
      h: size,
      vx: Number(knobs.speed) || 90,
      vy: 0,
      color: 0x8fa3b8,
      solid: false,
      gravityScale: 1,
      data: { homeX: 160, dir: 1, patrol: true }
    });
    robot.facing = 1;
    api.onTick(() => {
      const speed = Math.abs(Number(knobs.speed) || 90);
      const range = Math.max(10, Number(knobs.range) || 130);
      const r = api.byType("robot")[0];
      if (!r) return;
      if (typeof r.data.homeX !== "number") r.data.homeX = r.x;
      if (typeof r.data.dir !== "number") r.data.dir = 1;
      if (r.x > r.data.homeX + range) r.data.dir = -1;
      else if (r.x < r.data.homeX - range) r.data.dir = 1;
      if (r.onGround && Math.abs(r.vx) < 1 && api.tick() % 30 === 0) r.data.dir *= -1;
      r.vx = r.data.dir * speed;
      r.facing = r.data.dir >= 0 ? 1 : -1;
      if (api.tick() % 45 === 0) api.burst(r.x + r.w / 2, r.y - 2, 0x66d9ff, 1);
    });
  },
  dispose(api: any) {
    for (const e of api.byType("robot")) api.despawn(e.id);
  },
  test(t: any) {
    t.api.spawn({ type: "ground", x: -200, y: 400, w: 1200, h: 48, solid: true, gravityScale: 0 });
    const robots = t.api.byType("robot");
    t.expect(robots.length === 1, "exactly one robot spawned");
    const r = robots[0];
    const startX = r.x;
    t.step(30);
    t.expect(r.x > startX + 10, "robot patrols to the right");
    t.expect(Math.abs(r.vx) > 0, "robot keeps moving");
    t.step(240);
    t.expect(r.x < r.data.homeX + 145, "robot stays within patrol range");
    t.expect(r.data.dir === 1 || r.data.dir === -1, "robot has a patrol direction");
    t.expect(r.y + r.h <= 402, "robot lands on the ground");
  }
};

