var stdin_default = { id: "firefly-swarm", title: "Firefly Swarm", knobs: { count: { value: 24, min: 3, max: 60, label: "Count" }, speed: { value: 38, min: 10, max: 120, label: "Wander Speed" }, size: { value: 8, min: 4, max: 16, label: "Size" } }, setup(api, knobs) {
  const count = Math.max(3, Math.min(60, Math.round(Number(knobs.count) || 24)));
  const speed = Number(knobs.speed) || 38;
  const size = Number(knobs.size) || 8;
  const flies = [];
  for (let i = 0; i < count; i++) {
    const x = 40 + api.rand() * 560;
    const y = 120 + api.rand() * 200;
    const e = api.spawn({ type: "firefly", x, y, w: size, h: size, vx: 0, vy: 0, color: 16771174, solid: false, gravityScale: 0, data: { homeX: x, homeY: y, phase: api.rand() * 6.283, freq: 0.6 + api.rand() * 0.9, radius: 24 + api.rand() * 58, glow: 0 } });
    flies.push(e);
  }
  api.onTick((dt) => {
    const t = api.tick() / 60;
    for (const e of flies) {
      if (!api.entities().includes(e)) continue;
      const p = Number(e.data.phase) || 0;
      const f = Number(e.data.freq) || 1;
      const r = Number(e.data.radius) || 40;
      const hx = Number(e.data.homeX) || e.x;
      const hy = Number(e.data.homeY) || e.y;
      const tx = hx + Math.cos(t * f + p) * r;
      const ty = hy + Math.sin(t * f * 1.37 + p * 2) * r * 0.55;
      e.vx = Math.max(-speed * 2, Math.min(speed * 2, (tx - e.x) * 2));
      e.vy = Math.max(-speed * 2, Math.min(speed * 2, (ty - e.y) * 2));
      e.x += e.vx * dt;
      e.y += e.vy * dt;
      const pulse = 0.5 + 0.5 * Math.sin(t * (2 + f) + p * 3);
      e.data.glow = pulse;
      e.color = pulse > 0.72 ? 16774816 : pulse > 0.35 ? 16771174 : 13412898;
      if (pulse > 0.96 && api.tick() % 6 === 0) api.burst(e.x + e.w / 2, e.y + e.h / 2, 16771174, 1);
    }
  });
}, dispose(api) {
  for (const e of api.byType("firefly")) api.despawn(e.id);
}, test(t) {
  t.step(30);
  const flies = t.api.byType("firefly");
  t.expect(flies.length >= 3, "firefly swarm spawned");
  const before = flies[0].x + flies[0].y;
  t.step(30);
  t.expect(Math.abs(flies[0].x + flies[0].y - before) > 0.01, "fireflies wander and glow");
  t.expect(flies.every((f) => f.gravityScale === 0 && !f.solid), "fireflies float freely");
} };
